// Phase Detection: Data comes pre-processed from Syn_Gateway
const items = $input.all();
const item = items[0].json;

const threadTs = item.sessionId;
const channelId = item.channelId;
const userId = item.userId;
const cleanMessage = item.cleanMessage || '';
const hasFiles = item.hasFiles || false;

// Detect intent patterns
const isPersonaQuery = /^(frage an|ask|@|befrag)\s+/i.test(cleanMessage);
const isRigidityChange = /rigidity|rigidität|offener|härter|flexibler|standhafter/i.test(cleanMessage);
const isShowAnalysis = /^(zeig|show|was sagt|analyse von)\s+/i.test(cleanMessage);
const isRound3Trigger = /^(runde 3|round 3|weiter|nächste runde|convergence)/i.test(cleanMessage);
const isConfirmation = /^(ja|yes|ok|bestätigt|confirmed|go|los|start|passt|gut)/i.test(cleanMessage);
const isCancel = /^(abbruch|cancel|stop|nein|no)/i.test(cleanMessage);

let targetPersona = '';
if (isPersonaQuery) {
  const match = cleanMessage.match(/^(?:frage an|ask|@|befrag)\s+([\w\s]+?)(?::|,|\s+(?:was|wie|ob|whether|how|what))/i);
  if (match) targetPersona = match[1].trim();
}

let newRigidity = null;
if (isRigidityChange) {
  const scoreMatch = cleanMessage.match(/(\d+)/);
  if (scoreMatch) newRigidity = Math.min(10, Math.max(0, parseInt(scoreMatch[1])));
}

return [{
  json: {
    threadTs,
    channelId,
    userId,
    cleanMessage,
    hasFiles,
    isPersonaQuery,
    isRigidityChange,
    isShowAnalysis,
    isRound3Trigger,
    isConfirmation,
    isCancel,
    targetPersona,
    newRigidity,
    sessionId: threadTs
  }
}];

const items = $input.all();
const phaseData = $('Phase Detection').first().json;

// If DataTable returned 0 rows (no session exists yet), create a placeholder
// so the Route switch can evaluate the 'id notExists' condition
if (items.length === 0 || !items[0].json || Object.keys(items[0].json).length === 0) {
  return [{
    json: {
      _noSessionFound: true,
      ...phaseData
    }
  }];
}

// Session found - pass through with phase data merged
return [{
  json: {
    ...items[0].json,
    ...phaseData
  }
}];

const items = $input.all();
const trigger = $('Execute Workflow Trigger').first().json;

return items.map(item => ({
  json: {
    ...item.json,
    sessionId: trigger.sessionId,
    channelId: trigger.channelId,
    userId: trigger.userId
  }
}));
